echo '' | base64 -d > /tmp/clbff.zip
rm -rf /tmp/clbff; mkdir -p /tmp/clbff; unzip -oq /tmp/clbff.zip -d /tmp/clbff
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/clbff; rm -rf $D; mkdir -p $D; cd $D
cp /tmp/clbff/*.v /tmp/clbff/*.tcl $D/
for t in d_fdre d_fdce d_lat d_ce1 d_cepin; do /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; if grep -q "DONE_$t" $t.log; then echo "OK $t"; else echo "FAIL $t"; grep -m2 "^ERROR" $t.log; fi; done
tar czf /tmp/clbff_out.tgz *.bit 2>/dev/null || echo NOTAR
echo CLBFFDONE
